_RATES = {"USD": 1.0, "EUR": 0.9, "GBP": 0.8}
_cache = {}


def price_for(sku, currency):
    """Price of `sku` in `currency`, memoised."""
    if sku in _cache:                       # key ignores currency
        return _cache[sku]
    price = round(100 * _RATES[currency], 2)
    _cache[sku] = price
    return price

